<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, describeError } from '../api'
import { operations, operationState } from '../operations'
type Row = { id: string; name: string; status: string; managed: boolean; running: boolean; image: string; ports: number[] }
type Plan = { valid: boolean; selected: string[]; dependencies: string[]; steps: string[] }
const rows = ref<Row[]>([]), selected = ref<string[]>([]), passwords = ref<Record<string,string>>({}), minioUser = ref('minioadmin')
const plan = ref<Plan | null>(null), signature = ref(''), error = ref(''), message = ref(''), logs = ref<string[] | null>(null), logName = ref(''), loading = ref(false)
const busy = computed(() => loading.value || operationState.busy)
const dependencies = computed(() => selected.value.includes('milvus') ? ['etcd', 'minio'] : [])
const needed = computed(() => [...new Set([...selected.value, ...dependencies.value])].filter(id => !rows.value.find(r => r.id === id)?.managed))
const passwordIds = computed(() => needed.value.filter(id => ['mysql', 'redis', 'paradedb', 'neo4j', 'minio'].includes(id)))
const body = computed(() => ({ ids: selected.value, settings: Object.fromEntries([...passwordIds.value.map(id => [id+'_password', passwords.value[id] || '']), ...(passwordIds.value.includes('minio') ? [['minio_user', minioUser.value]] : [])]) }))
const ready = computed(() => plan.value?.valid && signature.value === JSON.stringify(body.value))
const statusNames: Record<string,string> = { healthy: '运行健康', unhealthy: '健康检查异常', stopped: '已停止', not_installed: '未安装', external: '外部部署 · 只读', unknown: '无法确认' }
async function refresh() { loading.value = true; try { rows.value = (await api<{components: Row[]}>('/api/ops/overview')).components; error.value = '' } catch (e) { error.value = describeError(e) } finally { loading.value = false } }
async function preflight() { loading.value = true; plan.value = null; try { const payload = JSON.stringify(body.value); plan.value = await api<Plan>('/api/ops/components/plan', { method: 'POST', body: payload }); signature.value = payload; error.value = '' } catch (e) { error.value = describeError(e) } finally { loading.value = false } }
async function install() { if (!ready.value || !window.confirm(`安装组件：${plan.value?.selected.join('、')}？`)) return; try { await operations.submit('/api/ops/components/install', { method: 'POST', body: JSON.stringify(body.value) }, '补装组件'); message.value = '所选组件已安装并通过健康检查'; selected.value = []; passwords.value = {}; plan.value = null; await refresh() } catch (e) { error.value = describeError(e) } }
async function action(row: Row, verb: string) { if (!window.confirm(`${({ start:'启动', stop:'停止', restart:'重启' } as Record<string,string>)[verb]} ${row.name}？使用该组件的应用可能受影响。`)) return; try { await operations.submit('/api/ops/components/action', { method:'POST', body:JSON.stringify({ id:row.id, action:verb }) }, row.name+' 运维'); await refresh() } catch (e) { error.value = describeError(e) } }
async function showLogs(row: Row) { try { logs.value = (await api<{lines:string[]}>('/api/ops/components/logs', { method:'POST', body:JSON.stringify({id:row.id}) })).lines; logName.value = row.name } catch(e) { error.value = describeError(e) } }
onMounted(refresh)
</script>
<template><section class="page-body ops-page">
  <div v-if="error" class="notice error-notice" role="alert">{{ error }}</div><div v-if="message" class="notice success-notice">{{ message }}</div>
  <section class="panel ops-section"><div class="panel-head"><div><h2>组件管理与补装</h2><p>选择所需组件，自动检查依赖、端口、现有数据与固定版本。已有凭据沿用，数据目录保留。</p></div><button class="secondary-button" :disabled="busy" @click="refresh">刷新状态</button></div>
  <div class="table-wrap"><table class="management-table"><thead><tr><th>选择</th><th>组件</th><th>状态</th><th>镜像 / 端口</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><input type="checkbox" v-model="selected" :value="row.id" :disabled="busy || !['not_installed','unhealthy','stopped'].includes(row.status)" :aria-label="`补装 ${row.name}`" /></td><td><strong>{{ row.name }}</strong></td><td><span :class="['ops-badge', row.status === 'healthy' ? 'good' : row.status === 'unhealthy' ? 'warn' : '']">{{ statusNames[row.status] }}</span></td><td><small>{{ row.image || (['nginx','etcd'].includes(row.id) ? '宿主服务' : '安装时按摘要拉取') }}</small><small>{{ row.ports.join(' / ') }}</small></td><td><div class="row-actions"><button class="secondary-button" :disabled="busy || !row.managed || row.running" @click="action(row,'start')">启动</button><button class="secondary-button" :disabled="busy || !row.managed || !row.running" @click="action(row,'stop')">停止</button><button class="secondary-button" :disabled="busy || !row.managed" @click="action(row,'restart')">重启</button><button class="secondary-button" :disabled="row.status === 'not_installed'" @click="showLogs(row)">日志</button></div></td></tr></tbody></table></div></section>
  <section class="panel ops-section"><h2>补装所选组件</h2><p>已选 {{ selected.length }} 项<span v-if="dependencies.length"> · Milvus 依赖：MinIO、etcd</span></p><label v-if="passwordIds.includes('minio')">MinIO 用户名<input v-model="minioUser" autocomplete="off" /></label><div class="ops-grid two-columns"><label v-for="id in passwordIds" :key="id">{{ id }} 密码<input v-model="passwords[id]" type="password" autocomplete="new-password" placeholder="12–128 个字符" /></label></div><div class="row-actions"><button class="secondary-button" :disabled="busy || !selected.length" @click="preflight">安装预检</button><button class="primary-button" :disabled="busy || !ready" @click="install">安装组件</button></div><template v-if="ready"><p>实际安装：{{ plan?.selected.join('、') }}</p><p>{{ plan?.steps.join(' → ') }}</p></template></section>
  <section v-if="logs" class="panel ops-section"><div class="panel-head"><h2>{{ logName }} 日志</h2><button class="secondary-button" @click="logs=null">关闭日志</button></div><pre class="ops-logs">{{ logs.join('\n') || '暂无日志' }}</pre></section>
</section></template>
